-- 009_game_templates_settings.sql
--
-- Reglages fins de Minecraft et Palworld.
--
-- Les schemas seedes en 007 ne couvraient qu'une poignee d'options (16 et 7).
-- Ils exposent desormais l'essentiel de ce que gerent les images Docker :
--   - itzg/minecraft-server               -> 39 reglages
--   - thijsvanloef/palworld-server-docker -> 49 reglages
--
-- Chaque champ porte un `group` : sans regroupement, cinquante champs a plat
-- sont inutilisables. Le front construit ses sections a partir de cette cle.
--
-- Rien n'est code en dur cote application : ajouter un reglage, ou un jeu
-- entier, se fait ici.

UPDATE game_templates SET config_schema = '[{"key": "MOTD", "label": "Message d''accueil", "type": "text", "group": "General", "default": "Serveur Minecraft", "max_length": 59}, {"key": "TYPE", "label": "Type de serveur", "type": "enum", "group": "General", "default": "VANILLA", "options": ["VANILLA", "PAPER", "SPIGOT", "FABRIC", "FORGE", "PURPUR"], "description": "PAPER est nettement plus performant. FORGE/FABRIC pour les mods."}, {"key": "VERSION", "label": "Version", "type": "text", "group": "General", "default": "LATEST", "description": "LATEST, ou une version precise (1.21.1)."}, {"key": "MODE", "label": "Mode de jeu", "type": "enum", "group": "General", "default": "survival", "options": ["survival", "creative", "adventure", "spectator"]}, {"key": "DIFFICULTY", "label": "Difficulte", "type": "enum", "group": "General", "default": "normal", "options": ["peaceful", "easy", "normal", "hard"]}, {"key": "HARDCORE", "label": "Hardcore", "type": "boolean", "group": "General", "default": "false", "description": "Mort definitive : le joueur passe en spectateur."}, {"key": "ICON", "label": "URL de l''icone du serveur", "type": "text", "group": "General", "default": "", "description": "Image 64x64 affichee dans la liste des serveurs."}, {"key": "MAX_PLAYERS", "label": "Joueurs maximum", "type": "number", "group": "Joueurs", "default": 20, "min": 1, "max": 200}, {"key": "ONLINE_MODE", "label": "Comptes Mojang verifies", "type": "boolean", "group": "Joueurs", "default": "true", "description": "Desactiver autorise les comptes crackes. A eviter."}, {"key": "WHITE_LIST", "label": "Liste blanche", "type": "boolean", "group": "Joueurs", "default": "false"}, {"key": "OPS", "label": "Operateurs (pseudos separes par des virgules)", "type": "text", "group": "Joueurs", "default": ""}, {"key": "OP_PERMISSION_LEVEL", "label": "Niveau des operateurs", "type": "number", "group": "Joueurs", "default": 4, "min": 1, "max": 4}, {"key": "PLAYER_IDLE_TIMEOUT", "label": "Expulsion apres inactivite (min)", "type": "number", "group": "Joueurs", "default": 0, "min": 0, "max": 180, "description": "0 = jamais."}, {"key": "ENFORCE_WHITELIST", "label": "Appliquer la liste blanche en direct", "type": "boolean", "group": "Joueurs", "default": "false"}, {"key": "PREVENT_PROXY_CONNECTIONS", "label": "Bloquer les VPN et proxys", "type": "boolean", "group": "Joueurs", "default": "false"}, {"key": "LEVEL_TYPE", "label": "Type de monde", "type": "enum", "group": "Monde", "default": "minecraft:normal", "options": ["minecraft:normal", "minecraft:flat", "minecraft:large_biomes", "minecraft:amplified"]}, {"key": "SEED", "label": "Graine du monde", "type": "text", "group": "Monde", "default": "", "description": "Vide = aleatoire."}, {"key": "MAX_WORLD_SIZE", "label": "Rayon maximum du monde (blocs)", "type": "number", "group": "Monde", "default": 29999984, "min": 1}, {"key": "SPAWN_PROTECTION", "label": "Rayon de protection du spawn", "type": "number", "group": "Monde", "default": 16, "min": 0, "max": 256}, {"key": "GENERATE_STRUCTURES", "label": "Generer les structures", "type": "boolean", "group": "Monde", "default": "true"}, {"key": "ALLOW_NETHER", "label": "Autoriser le Nether", "type": "boolean", "group": "Monde", "default": "true"}, {"key": "VIEW_DISTANCE", "label": "Distance d''affichage (chunks)", "type": "number", "group": "Monde", "default": 10, "min": 3, "max": 32, "description": "Le reglage le plus couteux en ressources."}, {"key": "SIMULATION_DISTANCE", "label": "Distance de simulation (chunks)", "type": "number", "group": "Monde", "default": 10, "min": 3, "max": 32}, {"key": "PVP", "label": "Combat entre joueurs", "type": "boolean", "group": "Gameplay", "default": "true"}, {"key": "SPAWN_ANIMALS", "label": "Apparition des animaux", "type": "boolean", "group": "Gameplay", "default": "true"}, {"key": "SPAWN_MONSTERS", "label": "Apparition des monstres", "type": "boolean", "group": "Gameplay", "default": "true"}, {"key": "SPAWN_NPCS", "label": "Apparition des villageois", "type": "boolean", "group": "Gameplay", "default": "true"}, {"key": "ALLOW_FLIGHT", "label": "Autoriser le vol", "type": "boolean", "group": "Gameplay", "default": "false", "description": "Necessaire avec certains mods, sinon source de triche."}, {"key": "FORCE_GAMEMODE", "label": "Forcer le mode de jeu a la connexion", "type": "boolean", "group": "Gameplay", "default": "false"}, {"key": "ENABLE_COMMAND_BLOCK", "label": "Blocs de commande", "type": "boolean", "group": "Gameplay", "default": "false"}, {"key": "ANNOUNCE_PLAYER_ACHIEVEMENTS", "label": "Annoncer les progres", "type": "boolean", "group": "Gameplay", "default": "true"}, {"key": "ENABLE_RCON", "label": "Console RCON", "type": "boolean", "group": "Technique", "default": "true", "description": "Requis pour la console web et le suivi des joueurs."}, {"key": "ENABLE_QUERY", "label": "Protocole Query", "type": "boolean", "group": "Technique", "default": "false"}, {"key": "MEMORY", "label": "Memoire JVM", "type": "text", "group": "Technique", "default": "", "description": "Vide = calcule depuis la memoire allouee au conteneur."}, {"key": "USE_AIKAR_FLAGS", "label": "Optimisations JVM (Aikar)", "type": "boolean", "group": "Technique", "default": "true", "description": "Reglages de collecte memoire recommandes pour Minecraft."}, {"key": "MAX_TICK_TIME", "label": "Delai avant plantage (ms)", "type": "number", "group": "Technique", "default": 60000, "min": -1}, {"key": "NETWORK_COMPRESSION_THRESHOLD", "label": "Seuil de compression reseau", "type": "number", "group": "Technique", "default": 256, "min": -1}, {"key": "SYNC_CHUNK_WRITES", "label": "Ecriture synchrone des chunks", "type": "boolean", "group": "Technique", "default": "true", "description": "Desactiver ameliore les performances, au prix du risque en cas de coupure."}, {"key": "RESOURCE_PACK", "label": "URL du pack de ressources", "type": "text", "group": "Technique", "default": ""}]'::jsonb, updated_at = now() WHERE slug = 'minecraft-vanilla';

UPDATE game_templates SET config_schema = '[{"key": "SERVER_NAME", "label": "Nom du serveur", "type": "text", "group": "General", "default": "Serveur Palworld"}, {"key": "SERVER_DESCRIPTION", "label": "Description", "type": "text", "group": "General", "default": ""}, {"key": "PLAYERS", "label": "Joueurs maximum", "type": "number", "group": "General", "default": 16, "min": 1, "max": 32}, {"key": "SERVER_PASSWORD", "label": "Mot de passe du serveur", "type": "text", "group": "General", "default": "", "description": "Vide = acces libre."}, {"key": "ADMIN_PASSWORD", "label": "Mot de passe administrateur", "type": "text", "group": "General", "default": ""}, {"key": "COMMUNITY", "label": "Serveur communautaire", "type": "boolean", "group": "General", "default": "false", "description": "Visible dans la liste publique du jeu."}, {"key": "PUBLIC_PORT", "label": "Port public annonce", "type": "number", "group": "General", "default": 8211, "min": 1024, "max": 65535}, {"key": "DIFFICULTY", "label": "Difficulte", "type": "enum", "group": "Difficulte", "default": "None", "options": ["None", "Casual", "Normal", "Hard"]}, {"key": "DEATH_PENALTY", "label": "Penalite de mort", "type": "enum", "group": "Difficulte", "default": "All", "options": ["None", "Item", "ItemAndEquipment", "All"]}, {"key": "IS_PVP", "label": "Combat entre joueurs", "type": "boolean", "group": "Difficulte", "default": "false"}, {"key": "ENABLE_PLAYER_TO_PLAYER_DAMAGE", "label": "Degats entre joueurs", "type": "boolean", "group": "Difficulte", "default": "false"}, {"key": "ENABLE_FRIENDLY_FIRE", "label": "Tir allie", "type": "boolean", "group": "Difficulte", "default": "false"}, {"key": "ENABLE_INVADER_ENEMY", "label": "Raids d''ennemis", "type": "boolean", "group": "Difficulte", "default": "true"}, {"key": "ENABLE_NON_LOGIN_PENALTY", "label": "Penalite hors connexion", "type": "boolean", "group": "Difficulte", "default": "true"}, {"key": "EXP_RATE", "label": "Gain d''experience", "type": "number", "group": "Taux de jeu", "default": 1, "min": 0.1, "max": 20}, {"key": "PAL_CAPTURE_RATE", "label": "Taux de capture des Pals", "type": "number", "group": "Taux de jeu", "default": 1, "min": 0.5, "max": 2}, {"key": "PAL_SPAWN_NUM_RATE", "label": "Densite de Pals sauvages", "type": "number", "group": "Taux de jeu", "default": 1, "min": 0.5, "max": 3}, {"key": "COLLECTION_DROP_RATE", "label": "Ressources recoltees", "type": "number", "group": "Taux de jeu", "default": 1, "min": 0.5, "max": 3}, {"key": "ENEMY_DROP_ITEM_RATE", "label": "Butin des ennemis", "type": "number", "group": "Taux de jeu", "default": 1, "min": 0.5, "max": 3}, {"key": "WORK_SPEED_RATE", "label": "Vitesse de travail", "type": "number", "group": "Taux de jeu", "default": 1, "min": 0.1, "max": 5}, {"key": "DAYTIME_SPEEDRATE", "label": "Vitesse du jour", "type": "number", "group": "Taux de jeu", "default": 1, "min": 0.1, "max": 5}, {"key": "NIGHTTIME_SPEEDRATE", "label": "Vitesse de la nuit", "type": "number", "group": "Taux de jeu", "default": 1, "min": 0.1, "max": 5}, {"key": "PAL_EGG_DEFAULT_HATCHING_TIME", "label": "Eclosion des oeufs (heures)", "type": "number", "group": "Taux de jeu", "default": 72, "min": 0, "max": 240}, {"key": "PLAYER_DAMAGE_RATE_ATTACK", "label": "Degats infliges (joueur)", "type": "number", "group": "Degats", "default": 1, "min": 0.1, "max": 5}, {"key": "PLAYER_DAMAGE_RATE_DEFENSE", "label": "Degats subis (joueur)", "type": "number", "group": "Degats", "default": 1, "min": 0.1, "max": 5}, {"key": "PAL_DAMAGE_RATE_ATTACK", "label": "Degats infliges (Pals)", "type": "number", "group": "Degats", "default": 1, "min": 0.1, "max": 5}, {"key": "PAL_DAMAGE_RATE_DEFENSE", "label": "Degats subis (Pals)", "type": "number", "group": "Degats", "default": 1, "min": 0.1, "max": 5}, {"key": "BUILD_OBJECT_DAMAGE_RATE", "label": "Degats aux constructions", "type": "number", "group": "Degats", "default": 1, "min": 0.1, "max": 5}, {"key": "BUILD_OBJECT_DETERIORATION_DAMAGE_RATE", "label": "Deterioration des constructions", "type": "number", "group": "Degats", "default": 1, "min": 0, "max": 5}, {"key": "PLAYER_STOMACH_DECREACE_RATE", "label": "Faim (joueur)", "type": "number", "group": "Survie", "default": 1, "min": 0.1, "max": 5}, {"key": "PLAYER_STAMINA_DECREACE_RATE", "label": "Endurance (joueur)", "type": "number", "group": "Survie", "default": 1, "min": 0.1, "max": 5}, {"key": "PLAYER_AUTO_HP_REGEN_RATE", "label": "Regeneration (joueur)", "type": "number", "group": "Survie", "default": 1, "min": 0.1, "max": 5}, {"key": "PLAYER_AUTO_HP_REGEN_RATE_IN_SLEEP", "label": "Regeneration au repos (joueur)", "type": "number", "group": "Survie", "default": 1, "min": 0.1, "max": 5}, {"key": "PAL_STOMACH_DECREACE_RATE", "label": "Faim (Pals)", "type": "number", "group": "Survie", "default": 1, "min": 0.1, "max": 5}, {"key": "PAL_STAMINA_DECREACE_RATE", "label": "Endurance (Pals)", "type": "number", "group": "Survie", "default": 1, "min": 0.1, "max": 5}, {"key": "PAL_AUTO_HP_REGEN_RATE", "label": "Regeneration (Pals)", "type": "number", "group": "Survie", "default": 1, "min": 0.1, "max": 5}, {"key": "GUILD_PLAYER_MAX_NUM", "label": "Membres max par guilde", "type": "number", "group": "Guildes et bases", "default": 20, "min": 1, "max": 100}, {"key": "BASE_CAMP_MAX_NUM", "label": "Camps de base max", "type": "number", "group": "Guildes et bases", "default": 128, "min": 1, "max": 256}, {"key": "BASE_CAMP_WORKER_MAX_NUM", "label": "Pals au travail par camp", "type": "number", "group": "Guildes et bases", "default": 15, "min": 1, "max": 50}, {"key": "DROP_ITEM_MAX_NUM", "label": "Objets au sol max", "type": "number", "group": "Guildes et bases", "default": 3000, "min": 100, "max": 10000}, {"key": "DROP_ITEM_ALIVE_MAX_HOURS", "label": "Duree des objets au sol (h)", "type": "number", "group": "Guildes et bases", "default": 1, "min": 0, "max": 48}, {"key": "AUTO_RESET_GUILD_NO_ONLINE_PLAYERS", "label": "Dissoudre les guildes inactives", "type": "boolean", "group": "Guildes et bases", "default": "false"}, {"key": "ENABLE_DEFENSE_OTHER_GUILD_PLAYER", "label": "Defense contre les autres guildes", "type": "boolean", "group": "Guildes et bases", "default": "false"}, {"key": "MULTITHREADING", "label": "Multithreading", "type": "boolean", "group": "Technique", "default": "true", "description": "Palworld exploite reellement plusieurs coeurs : a laisser actif."}, {"key": "RCON_ENABLED", "label": "Console RCON", "type": "boolean", "group": "Technique", "default": "true"}, {"key": "RCON_PORT", "label": "Port RCON", "type": "number", "group": "Technique", "default": 25575, "min": 1024, "max": 65535}, {"key": "UPDATE_ON_BOOT", "label": "Mettre a jour au demarrage", "type": "boolean", "group": "Technique", "default": "true"}, {"key": "BACKUP_ENABLED", "label": "Sauvegardes automatiques", "type": "boolean", "group": "Technique", "default": "true"}, {"key": "ENABLE_FAST_TRAVEL", "label": "Voyage rapide", "type": "boolean", "group": "Technique", "default": "true"}]'::jsonb, updated_at = now() WHERE slug = 'palworld';


-- Palworld gere RCON (RCON_ENABLED) : la console web doit lui etre proposee.
UPDATE game_templates SET supports_rcon = true WHERE slug = 'palworld';
